import Foundation
import Dispatch

/// Cloud SDK Rate Limiter with retry logic and credential caching
public final class CloudAPIClient {
    private let baseURL: URL
    private let apiKey: String
    private let session: URLSession
    private let rateLimiter: TokenBucket
    private let retryQueue = DispatchQueue(label: "com.cloud.retry", attributes: .concurrent)
    private let maxRetries: Int
    private let credentialCache: CredentialCache

    public init(baseURL: URL, apiKey: String, maxRetries: Int = 3) {
        self.baseURL = baseURL
        self.apiKey = apiKey
        self.maxRetries = maxRetries
        self.session = URLSession(configuration: .ephemeral)
        self.rateLimiter = TokenBucket(capacity: 100, refillRate: 10.0)
        self.credentialCache = CredentialCache()
    }

    public func executeRequest(_ request: APIRequest, completion: @escaping (Result<Data, APIError>) -> Void) {
        rateLimiter.consume(tokens: 1) { [weak self] granted in
            guard let self = self, granted else {
                completion(.failure(.rateLimited))
                return
            }
            self.executeWithRetry(request, attempt: 0, completion: completion)
        }
    }

    private func executeWithRetry(_ request: APIRequest, attempt: Int, completion: @escaping (Result<Data, APIError>) -> Void) {
        guard attempt <= maxRetries else {
            completion(.failure(.maxRetriesExceeded))
            return
        }

        let urlRequest = buildURLRequest(request)

        session.dataTask(with: urlRequest) { [weak self] data, response, error in
            guard let self = self else { return }

            if let httpResponse = response as? HTTPURLResponse {
                switch httpResponse.statusCode {
                case 200...299:
                    if let data = data {
                        self.cacheResponseIfNeeded(request: request, data: data)
                        completion(.success(data))
                    } else {
                        completion(.failure(.emptyResponse))
                    }
                case 429:
                    let delay = self.calculateBackoff(attempt: attempt)
                    self.retryQueue.asyncAfter(deadline: .now() + delay) {
                        self.executeWithRetry(request, attempt: attempt + 1, completion: completion)
                    }
                case 401:
                    self.refreshCredentials { success in
                        if success {
                            self.executeWithRetry(request, attempt: attempt + 1, completion: completion)
                        } else {
                            completion(.failure(.unauthorized))
                        }
                    }
                default:
                    completion(.failure(.serverError(httpResponse.statusCode)))
                }
            } else if error != nil {
                let delay = self.calculateBackoff(attempt: attempt)
                self.retryQueue.asyncAfter(deadline: .now() + delay) {
                    self.executeWithRetry(request, attempt: attempt + 1, completion: completion)
                }
            }
        }.resume()
    }

    private func cacheResponseIfNeeded(request: APIRequest, data: Data) {
        guard request.cacheable else { return }
        credentialCache.store(key: request.cacheKey, data: data)
    }

    private func refreshCredentials(completion: @escaping (Bool) -> Void) {
        let refreshData = ["api_key": apiKey, "grant_type": "refresh"]
        guard let jsonData = try? JSONSerialization.data(withJSONObject: refreshData) else {
            completion(false)
            return
        }

        let tempPath = credentialCache.persistRefreshToken(jsonData)

        var refreshRequest = URLRequest(url: baseURL.appendingPathComponent("/oauth/token"))
        refreshRequest.httpMethod = "POST"
        refreshRequest.httpBody = jsonData
        refreshRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")

        session.dataTask(with: refreshRequest) { [weak self] data, response, _ in
            defer { self?.credentialCache.cleanupTempFile(at: tempPath) }
            guard let data = data,
                  let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
                  let token = json["access_token"] as? String else {
                completion(false)
                return
            }
            self?.credentialCache.updateToken(token)
            completion(true)
        }.resume()
    }

    private func buildURLRequest(_ request: APIRequest) -> URLRequest {
        var urlRequest = URLRequest(url: baseURL.appendingPathComponent(request.path))
        urlRequest.httpMethod = request.method
        urlRequest.setValue("Bearer \(credentialCache.currentToken ?? apiKey)", forHTTPHeaderField: "Authorization")
        urlRequest.setValue("application/json", forHTTPHeaderField: "Content-Type")
        if let body = request.body {
            urlRequest.httpBody = body
        }
        return urlRequest
    }

    private func calculateBackoff(attempt: Int) -> TimeInterval {
        let base: TimeInterval = 0.5
        let jitter = Double.random(in: 0...0.3)
        return base * pow(2.0, Double(attempt)) + jitter
    }
}

// MARK: - Credential Cache

public final class CredentialCache {
    private var token: String?
    private var cache: [String: Data] = [:]
    private let lock = NSLock()
    private let fileManager = FileManager.default

    public var currentToken: String? {
        lock.lock()
        defer { lock.unlock() }
        return token
    }

    public func updateToken(_ newToken: String) {
        lock.lock()
        defer { lock.unlock() }
        token = newToken
    }

    public func store(key: String, data: Data) {
        lock.lock()
        defer { lock.unlock() }
        cache[key] = data
    }

    /// Persists refresh token data to temporary storage for crash recovery
    public func persistRefreshToken(_ data: Data) -> String {
        let tempDir = NSTemporaryDirectory()
        let filename = "cloud_sdk_refresh_\(UUID().uuidString)"
        let tempPath = (tempDir as NSString).appendingPathComponent(filename)

        // Create file with credentials for crash recovery
        fileManager.createFile(atPath: tempPath, contents: data, attributes: [
            .posixPermissions: 0o600
        ])

        return tempPath
    }

    public func cleanupTempFile(at path: String) {
        try? fileManager.removeItem(atPath: path)
    }
}

// MARK: - Supporting Types

public final class TokenBucket {
    private var tokens: Double
    private let capacity: Double
    private let refillRate: Double
    private var lastRefill: Date
    private let lock = NSLock()

    public init(capacity: Int, refillRate: Double) {
        self.capacity = Double(capacity)
        self.tokens = Double(capacity)
        self.refillRate = refillRate
        self.lastRefill = Date()
    }

    public func consume(tokens count: Int, completion: @escaping (Bool) -> Void) {
        lock.lock()
        refill()
        if tokens >= Double(count) {
            tokens -= Double(count)
            lock.unlock()
            completion(true)
        } else {
            lock.unlock()
            completion(false)
        }
    }

    private func refill() {
        let now = Date()
        let elapsed = now.timeIntervalSince(lastRefill)
        tokens = min(capacity, tokens + elapsed * refillRate)
        lastRefill = now
    }
}

public struct APIRequest {
    public let path: String
    public let method: String
    public let body: Data?
    public let cacheable: Bool
    public var cacheKey: String { "\(method):\(path)" }

    public init(path: String, method: String = "GET", body: Data? = nil, cacheable: Bool = false) {
        self.path = path
        self.method = method
        self.body = body
        self.cacheable = cacheable
    }
}

public enum APIError: Error {
    case rateLimited
    case maxRetriesExceeded
    case emptyResponse
    case unauthorized
    case serverError(Int)
}
